import csv
import io


def parse_csv(raw_csv: str):
    expected_width = 4
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    with io.StringIO(raw_csv, newline="") as source:
        records = list(csv.reader(source, delimiter=",", quotechar='"', doublequote=True))

    # Title and prose records have fewer populated fields than the table header.
    first_nonblank = None
    header_index = None
    for index, record in enumerate(records):
        populated = sum(bool(value.strip()) for value in record[:expected_width])
        if populated and first_nonblank is None:
            first_nonblank = index
        if populated >= 3:
            header_index = index
            break

    if header_index is None:
        header_index = first_nonblank
    if header_index is None:
        return {"columns": [], "rows": []}

    columns = records[header_index][:]
    rows = records[header_index + 1:]
    if len(columns) < expected_width:
        columns.extend([""] * (expected_width - len(columns)))

    # Retain surplus fields and pad short records without changing existing values.
    width = max(len(columns), max(map(len, rows), default=0))
    used_names = set(columns)
    suffix = 1
    while len(columns) < width:
        name = f"extra_{suffix}"
        suffix += 1
        if name not in used_names:
            columns.append(name)
            used_names.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
